cypress_script:
describe('Slider Control Tests', () => {
  it('should adjust the slider value correctly', () => {
    cy.visit('https://demoqa.com/slider');
    cy.get('#slider').invoke('val', 75).trigger('input');
    cy.get('#sliderValue').should('have.value', '75');
  });

  it('should not change the value if the slider is not moved', () => {
    cy.visit('https://demoqa.com/slider');
    cy.get('#slider').invoke('val', 25).trigger('input');
    cy.get('#sliderValue').should('have.value', '25');
  });
});

playwright_script:
import { test, expect } from '@playwright/test';

test.describe('Slider Control Tests', () => {
  test('should adjust the slider value correctly', async ({ page }) => {
    await page.goto('https://demoqa.com/slider');
    await page.locator('#slider').fill('75');
    await expect(page.locator('#sliderValue')).toHaveValue('75');
  });

  test('should not change the value if the slider is not moved', async ({ page }) => {
    await page.goto('https://demoqa.com/slider');
    await page.locator('#slider').fill('25');
    await expect(page.locator('#sliderValue')).toHaveValue('25');
  });
});
